def match(orders):
    trades = []
    buy_book = []  # List of (price, arrival_time, id, qty) - sorted by price desc, then arrival_time asc
    sell_book = []  # List of (price, arrival_time, id, qty) - sorted by price asc, then arrival_time asc
    resting_orders = {}  # id -> (side, price, arrival_time, qty, index_in_book)
    time_counter = 0

    for order in orders:
        time_counter += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in resting_orders:
                side, price, arrival_time, qty, idx = resting_orders[order_id]
                if side == 'buy':
                    if idx < len(buy_book) and buy_book[idx][2] == order_id:
                        buy_book.pop(idx)
                        # Update indices for all orders after this one
                        for i in range(idx, len(buy_book)):
                            oid = buy_book[i][2]
                            if oid in resting_orders:
                                s, p, at, q, _ = resting_orders[oid]
                                resting_orders[oid] = (s, p, at, q, i)
                else:  # side == 'sell'
                    if idx < len(sell_book) and sell_book[idx][2] == order_id:
                        sell_book.pop(idx)
                        # Update indices for all orders after this one
                        for i in range(idx, len(sell_book)):
                            oid = sell_book[i][2]
                            if oid in resting_orders:
                                s, p, at, q, _ = resting_orders[oid]
                                resting_orders[oid] = (s, p, at, q, i)
                del resting_orders[order_id]

        else:
            order_type = order[0]
            order_id = order[1]
            side = order[2]
            qty = order[3] if order_type == 'market' else order[4]
            price = None if order_type == 'market' else order[3]

            remaining_qty = qty

            if side == 'buy':
                # Match against sell book
                i = 0
                while i < len(sell_book) and remaining_qty > 0:
                    sell_price, sell_arrival, sell_id, sell_qty = sell_book[i]

                    # Check if price matches
                    if order_type == 'market' or price >= sell_price:
                        trade_qty = min(remaining_qty, sell_qty)
                        trades.append([order_id, sell_id, sell_price, trade_qty])
                        remaining_qty -= trade_qty
                        sell_qty -= trade_qty

                        if sell_qty == 0:
                            sell_book.pop(i)
                            del resting_orders[sell_id]
                            # Update indices for all orders after this one
                            for j in range(i, len(sell_book)):
                                oid = sell_book[j][2]
                                if oid in resting_orders:
                                    s, p, at, q, _ = resting_orders[oid]
                                    resting_orders[oid] = (s, p, at, q, j)
                        else:
                            sell_book[i] = (sell_price, sell_arrival, sell_id, sell_qty)
                            if sell_id in resting_orders:
                                s, p, at, _, idx = resting_orders[sell_id]
                                resting_orders[sell_id] = (s, p, at, sell_qty, idx)
                            i += 1
                    else:
                        break

                # Add to book if remaining and limit order
                if remaining_qty > 0 and order_type == 'limit':
                    buy_book.append((price, time_counter, order_id, remaining_qty))
                    # Sort buy book: highest price first, then earliest arrival
                    buy_book.sort(key=lambda x: (-x[0], x[1]))
                    # Update indices
                    for i, (p, at, oid, q) in enumerate(buy_book):
                        if oid in resting_orders or oid == order_id:
                            resting_orders[oid] = ('buy', p, at, q, i)
                        else:
                            resting_orders[oid] = ('buy', p, at, q, i)

            else:  # side == 'sell'
                # Match against buy book
                i = 0
                while i < len(buy_book) and remaining_qty > 0:
                    buy_price, buy_arrival, buy_id, buy_qty = buy_book[i]

                    # Check if price matches
                    if order_type == 'market' or price <= buy_price:
