                                    s, p, at, q, _ = resting_orders[oid]
                                    resting_orders[oid] = (s, p, at, q, j)
                        else:
                            buy_book[i] = (buy_price, buy_arrival, buy_id, buy_qty)
                            if buy_id in resting_orders:
                                s, p, at, _, idx = resting_orders[buy_id]
                                resting_orders[buy_id] = (s, p, at, buy_qty, idx)
                            i += 1
                    else:
                        break

                # Add to book if remaining and limit order
                if remaining_qty > 0 and order_type == 'limit':
                    sell_book.append((price, time_counter, order_id, remaining_qty))
                    # Sort sell book: lowest price first, then earliest arrival
